<div class="grid gap-5 md:grid-cols-2"><div><label class="text-sm font-semibold text-slate-700">Account Code <span class="text-rose-500">*</span></label><input id="account-code" name="code" value="{{ old('code', $account->code ?? '') }}" required placeholder="Example: 1000101" class="mt-2 block w-full rounded-md border-slate-300 px-3 py-2.5 text-sm"><p id="account-code-help" class="mt-1 text-xs text-slate-400">Primary heads use a manual code. Sub-account codes are generated automatically.</p><x-input-error :messages="$errors->get('code')" class="mt-2" /></div><div><label class="text-sm font-semibold text-slate-700">Account Name <span class="text-rose-500">*</span></label><input name="name" value="{{ old('name', $account->name ?? '') }}" required placeholder="Example: Cash in Hand" class="mt-2 block w-full rounded-md border-slate-300 px-3 py-2.5 text-sm"><x-input-error :messages="$errors->get('name')" class="mt-2" /></div><div><label class="text-sm font-semibold text-slate-700">Account Type <span class="text-rose-500">*</span></label><select id="account-type" name="account_type" required class="mt-2 block w-full rounded-md border-slate-300 py-2.5 text-sm">@foreach(['asset'=>'Asset','liability'=>'Liability','equity'=>'Equity','income'=>'Income','expense'=>'Expense'] as $value => $label)<option value="{{ $value }}" @selected(old('account_type', $account->account_type ?? $defaultAccountType ?? 'asset') === $value)>{{ $label }}</option>@endforeach</select></div><div><label class="text-sm font-semibold text-slate-700">Parent Account</label><select id="parent-account" name="parent_id" class="mt-2 block w-full rounded-md border-slate-300 py-2.5 text-sm"><option value="">Primary account head</option>@foreach($parents as $parent)<option value="{{ $parent->id }}" data-code="{{ $parent->code }}" data-type="{{ $parent->account_type }}" @selected((string) old('parent_id', $account->parent_id ?? $defaultParentId ?? '') === (string) $parent->id)>{{ $parent->code }} — {{ $parent->name }}</option>@endforeach</select><p class="mt-1 text-xs text-slate-400">A sub account uses its parent's type; its code is automatic.</p></div></div><div class="mt-5 flex flex-wrap gap-6"><label class="flex items-center gap-2 text-sm text-slate-700"><input type="checkbox" name="is_transactional" value="1" @checked(old('is_transactional', $account->is_transactional ?? false)) class="rounded border-slate-300 text-blue-600">Used in transactions</label><label class="flex items-center gap-2 text-sm text-slate-700"><input type="checkbox" name="is_active" value="1" @checked(old('is_active', $account->is_active ?? true)) class="rounded border-slate-300 text-blue-600">Active</label></div><div class="mt-7 flex gap-3 border-t border-slate-100 pt-5"><a href="{{ route('accounts.index') }}" class="rounded-md border border-slate-300 bg-white px-5 py-2.5 text-sm font-semibold text-slate-700">Cancel</a><button class="rounded-md bg-gradient-to-r from-[#4165dd] to-[#4432f2] px-5 py-2.5 text-sm font-semibold text-white shadow">{{ isset($account) ? 'Update Account' : 'Save Account' }}</button></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const p=document.getElementById('parent-account'),c=document.getElementById('account-code'),t=document.getElementById('account-type'),h=document.getElementById('account-code-help'),children=@json($childCodesByParent ?? []),current=@json(isset($account)?$account->parent_id:null),inc=v=>{let d=v.split('');for(let i=d.length-1;i>=0;i--){if(d[i]!=='9'){d[i]=String(Number(d[i])+1);return d.join('')}d[i]='0'}return '1'+d.join('')},refresh=()=>{let o=p.options[p.selectedIndex];if(!p.value){c.readOnly=false;h.textContent='Primary heads use a manual code. Sub-account codes are generated automatically.';return}t.value=o.dataset.type;c.readOnly=true;let a=(children[p.value]||[]).filter(x=>/^\d+$/.test(x)).sort((x,y)=>x.length-y.length||x.localeCompare(y)),n=a.length?inc(a.at(-1)):o.dataset.code+'1';if(current!==Number(p.value)||!c.value)c.value=n;h.textContent='Auto-generated from '+o.dataset.code+': '+c.value};p.addEventListener('change',refresh);refresh()});</script>
